    /**
     * Compares the properties of this instance to the properties of the argument. This method will return
     * {@code false} as soon as it detects that the argument is {@code null} or not of the same type as
     * (or a sub-type of) this instance's type.
     *
     * <p/>For array, collection or map properties the comparison will be done one level deep, in other words:
     * the elements will be compared using the {@code equals()} operation.
     *
     * <p/>Note that two properties will be considered equal when both values are {@code null}.
     *
     * @param thatObject the object containing the properties to compare against this instance
     * @return this method will return {@code true} in case the argument has the same type as this class, or is a
     *      sub-type of this class and all properties as found on this class have equal values when queried on that
     *      argument instance; in all other cases this method will return {@code false}
     */
    public boolean equalProperties(final Object thatObject)
    {
        if (thatObject == null || !this.getClass().isAssignableFrom(thatObject.getClass()))
        {
            return false;
        }

        final SigningSessionDTO that = (SigningSessionDTO)thatObject;
        return
            equal(this.getInvitationStatus(), that.getInvitationStatus())
            && equal(this.getWorkflowReference(), that.getWorkflowReference())
            && equal(this.getWorkflowTitle(), that.getWorkflowTitle())
            && equal(this.getMessage(), that.getMessage())
            && equal(this.getDocumentTitle(), that.getDocumentTitle())
            && equal(this.getPageCount(), that.getPageCount())
            && equal(this.getOrganisationName(), that.getOrganisationName())
            && equal(this.getBranding(), that.getBranding())
            && equal(this.getSignatoryName(), that.getSignatoryName())
            && equal(this.getSignatoryEmailMasked(), that.getSignatoryEmailMasked())
            && equal(this.getSignatoryStatus(), that.getSignatoryStatus())
            && equal(this.getVerificationRequired(), that.getVerificationRequired())
            && equal(this.getVerificationMethod(), that.getVerificationMethod())
            && equal(this.getVerified(), that.getVerified())
            && equal(this.getExpiresAt(), that.getExpiresAt())
            && equal(this.getCanDecline(), that.getCanDecline())
            && equal(this.getRequireDeclineReason(), that.getRequireDeclineReason())
            && equal(this.getConsentText(), that.getConsentText())
            && equal(this.getAllowedCaptureMethods(), that.getAllowedCaptureMethods())
            && equal(this.getFields(), that.getFields())
            && equal(this.getPages(), that.getPages())
            && equal(this.getAlreadySigned(), that.getAlreadySigned())
        ;
    }

    /**
     * This is a convenient helper method which is able to detect whether or not two values are equal. Two values
     * are equal when they are both {@code null}, are arrays of the same length with equal elements or are
     * equal objects (this includes {@link java.util.Collection} and {@link java.util.Map} instances).
     *
     * <p/>Note that for array, collection or map instances the comparison runs one level deep.
     *
     * @param first the first object to compare, may be {@code null}
     * @param second the second object to compare, may be {@code null}
     * @return this method will return {@code true} in case both objects are equal as explained above;
     *      in all other cases this method will return {@code false}
     */
    protected static boolean equal(final Object first, final Object second)
    {
        final boolean equal;

        if (first == null)
        {
            equal = (second == null);
        }
        else if (first.getClass().isArray() && (second != null) && second.getClass().isArray())
        {
            equal = Arrays.equals((Object[])first, (Object[])second);
        }
        else // note that the following also covers java.util.Collection and java.util.Map
        {
            equal = first.equals(second);
        }

        return equal;
    }

